export const DESC_LARGAS_CLASES: Record<string, string> = {
  'artifice': 'Maestros de la invención que transforman la magia bruta en maravillas mecánicas y objetos imbuidos. Consumen su tiempo en crear infusiones que mejoran permanentemente el equipo de sus aliados. Brillan como apoyo táctico y solucionadores de problemas, adaptando sus artilugios a las necesidades del grupo para superar cualquier obstáculo físico o mágico que encuentren.',
  'barbaro': 'Combatientes feroces que desatan una ira inagotable para destrozar las líneas enemigas. Gastan usos de su Furia para volverse resistentes al daño físico y asestar golpes devastadores cuerpo a cuerpo. Cumplen el papel de tanque agresivo en el grupo, brillando en el centro de la batalla, donde absorben castigo masivo mientras aniquilan a sus oponentes sin dudarlo.',
  'bardo': 'Eruditos polifacéticos que moldean la realidad mediante la música, la oratoria y la magia arcana. Gastan usos de Inspiración Bárdica para potenciar las tiradas de sus aliados o mermar a los enemigos. Operan como el pilar social y de apoyo del grupo, brillando al manipular la mente de los rivales y curar a los caídos, manteniendo la moral alta en pleno combate.',
  'brujo': 'Buscadores de conocimiento que forjan alianzas peligrosas para obtener un inmenso poder arcano. Gastan espacios de conjuro que recuperan rápidamente para lanzar magia destructiva o de control. Funcionan como atacantes a distancia sostenidos, brillando gracias a sus invocaciones personalizadas y ráfagas constantes que debilitan y destruyen a los enemigos del grupo.',
  'clerigo': 'Representantes divinos que canalizan la voluntad de sus dioses para proteger a los creyentes y castigar a los herejes. Consumen espacios de conjuro y su Canalizar Divinidad para sanar heridas letales o invocar poder sagrado. Actúan como el soporte principal del equipo, brillando al mantener vivos a sus aliados mientras fulminan a los muertos vivientes y demonios.',
  'druida': 'Custodios de la naturaleza que extraen su magia de los ciclos de la vida, la muerte y los elementos. Gastan usos de su Forma Salvaje para transformarse en bestias formidables o potenciar sus habilidades primigenias. Cumplen un rol de control y adaptabilidad, brillando al invocar aliados naturales, dominar el terreno y sobrevivir en los entornos más hostiles.',
  'explorador': 'Supervivientes natos que combinan tácticas de guerrilla con magia primigenia para dominar los entornos salvajes. Consumen espacios de conjuro para marcar a sus presas y potenciar el daño de sus armas. Operan como hostigadores y guías del grupo, brillando al rastrear enemigos escurridizos, eliminar objetivos aislados y liderar marchas a través de territorios peligrosos.',
  'guerrero': 'Veteranos del campo de batalla que dominan todas las formas de combate físico y táctica militar. Utilizan su Oleada de Acción y Nuevas Energías para atacar sin descanso y mantenerse en pie cuando otros caerían. Cumplen el rol de defensores inquebrantables o atacantes letales, brillando al asestar múltiples golpes por turno y adaptarse a cualquier tipo de armamento.',
  'hechicero': 'Conductos vivos de la magia que manipulan las fuerzas arcanas desde su propia línea de sangre. Gastan Puntos de Hechicería para alterar la naturaleza de sus conjuros, volviéndolos más rápidos, potentes o sutiles. Operan como artillería mágica, brillando al desatar explosiones devastadoras o controlar multitudes, rompiendo las reglas del lanzamiento de conjuros normal.',
  'mago': 'Eruditos académicos que alteran el tejido de la realidad mediante un estudio riguroso y grimorios ancestrales. Gastan espacios de conjuro de un vasto arsenal para resolver casi cualquier problema mágico o físico. Cumplen el rol de utilidad absoluta y control de área, brillando al descubrir debilidades enemigas y alterar el campo de batalla con ilusiones o explosiones.',
  'monje': 'Artistas marciales perfeccionados que fluyen por el campo de batalla combinando velocidad e instinto. Gastan Puntos de Enfoque para desatar ráfagas de golpes, aturdir a sus rivales o evadir el peligro con agilidad sobrenatural. Operan como atacantes de escaramuza, brillando al esquivar proyectiles, cruzar grandes distancias y neutralizar amenazas prioritarias rápidamente.',
  'paladin': 'Campeones acorazados que juran defender un ideal con su espada y su propia vida. Consumen espacios de conjuro para potenciar sus ataques con Castigos divinos devastadores y utilizan su Imposición de Manos para curar aliados. Cumplen el rol de líderes y defensores de vanguardia, brillando al irradiar auras protectoras y aniquilar enemigos clave de un solo golpe crítico.',
  'picaro': 'Especialistas del subterfugio que aprovechan cualquier distracción para asestar un golpe letal. No gastan recursos mágicos, dependiendo de su astucia para usar Ataque Furtivo y acciones ágiles en combate. Operan como atacantes precisos e infiltradores, brillando al desactivar trampas, abrir cerraduras y eliminar blancos vulnerables sin ser detectados por el enemigo.',
  'arcanista': 'Artesanos de lo arcano que estudian el funcionamiento interno de la magia para crear maravillas portátiles. Gastan su tiempo para imbuir objetos mundanos con poder constante, creando herramientas que el grupo necesita. Funcionan como solucionadores de problemas, brillando al otorgar equipo mágico a sus aliados y desatar efectos arcanos con precisión de relojero.',
  'cazador-sangre': 'Especialistas oscuros que se inyectan toxinas letales para combatir a los monstruos con sus propias armas. Gastan su propia vitalidad para invocar ritos elementales sobre sus armas y maldecir a sus presas. Actúan como atacantes tácticos de desgaste, brillando al rastrear criaturas por sus rastros más sutiles y castigar implacablemente a los enemigos que osan dañarlos.',
};
export const DESC_LARGAS_SUBCLASES: Record<string, string> = {
  'alquimista': 'Especialistas en brebajes que mezclan ciencia y magia para curar, potenciar o destruir. Gastan espacios de conjuro para crear elixires experimentales que otorgan beneficios impredecibles pero vitales al equipo. Actúan como sanadores y atacantes elementales, brillando al explotar vulnerabilidades a toxinas y alzar a sus aliados con medicina mágica en momentos críticos.',
  'armero': 'Ingenieros defensivos que forjan armaduras arcanas impenetrables que funcionan como su segunda piel. Utilizan su armadura para generar ataques de fuerza o campos de energía, atrayendo la atención enemiga. Cumplen el rol de defensores inquebrantables o infiltradores silenciosos, brillando al adaptar sus mejoras en tiempo real para sobrevivir a los golpes más letales.',
  'artillero': 'Creadores de armas de asedio en miniatura que dominan el campo de batalla mediante fuego pesado. Consumen recursos para desplegar cañones arcanos que protegen a los aliados o incineran a las filas enemigas. Operan como artillería y control de área, brillando al mantener posiciones defensivas y desatar ráfagas constantes de daño mágico desde largas distancias.',
  'herrero-batalla': 'Forjadores de guerra que combaten codo a codo con un guardián mecánico que ellos mismos han construido. Utilizan su inteligencia para dirigir ataques marciales precisos y curar con su magia reparadora. Actúan como combatientes de primera línea y apoyo, brillando al flanquear enemigos con su defensor de acero y absorber el daño que iba dirigido a sus aliados.',
  'cartografo': 'Trazadores de rutas mágicas que alteran el posicionamiento de todo el campo de batalla. Gastan su conocimiento para crear mapas vivos que guían los ataques aliados y permiten teletransportes rápidos. Funcionan como estrategas de movilidad, brillando al rescatar a compañeros de la muerte segura y asegurar que el grupo nunca pierda la ventaja del terreno a su favor.',
  'reanimador': 'Científicos macabros que fusionan tejido muerto con energía arcana para crear siervos incansables. Gastan su ingenio para mantener y mejorar a su creación no muerta, usándola como conducto para sus propios hechizos. Operan como atacantes de desgaste, brillando al abrumar al enemigo con daño necrótico letal y provocar explosiones tóxicas al sacrificar a su esbirro.',
  'senda-berserker': 'Combatientes desenfrenados que canalizan su rabia absoluta en una ofensiva brutal e incesante. Consumen su Furia para volverse inmunes al miedo y realizar ataques adicionales que aplastan defensas. Actúan como la vanguardia destructiva del grupo, brillando al contraatacar a quienes se atreven a herirlos e intimidar a multitudes con su sola presencia aterradora.',
  'senda-corazon-salvaje': 'Guerreros chamánicos que imitan las tácticas de los depredadores más letales del mundo natural. Gastan su Furia para adoptar aspectos animales que les otorgan resistencia excepcional o ventajas de movilidad. Cumplen el rol de atacantes adaptables, brillando al cambiar de táctica según el enemigo, ya sea derribando rivales como un lobo o volando sobre ellos como un águila.',
  'senda-arbol-mundo': 'Defensores místicos conectados a las raíces del cosmos que nutren a sus aliados en plena matanza. Utilizan su Furia para canalizar energía vital, otorgando resistencia constante al grupo y manipulando el espacio. Actúan como tanques de control, brillando al teletransportarse por el campo de batalla y arrastrar enemigos lejos de los aliados vulnerables del equipo.',
  'senda-fanatico': 'Cruzados de la furia que luchan con el fervor sagrado de dioses de la guerra y la destrucción. Gastan su vitalidad para desatar daño divino o necrótico, resistiendo la muerte misma por pura devoción. Operan como atacantes inmortales, brillando al inspirar a sus compañeros en las batallas más desesperadas y negarse a caer inconscientes aunque sufran heridas fatales.',
  'senda-rabioso-batalla': 'Matones acorazados que se lanzan al combate cubiertos de pinchos letales. Gastan su Furia para embestir y desgarrar a los enemigos con su propia armadura, ignorando su propia seguridad. Operan como atacantes temerarios, brillando al generar daño pasivo a quienes intentan agarrarlos y ganar resistencia temporal con cada golpe salvaje que logran asestar con éxito.',
  'senda-bestia': 'Cambiaformas ferales que dejan atrás su humanidad para desatar su lado más monstruoso. Utilizan su Furia para manifestar garras, mandíbulas y colas letales, atacando con un salvajismo contagioso. Actúan como combatientes de primera línea altamente letales, brillando al enloquecer a los enemigos y cazar junto a sus aliados como una auténtica manada de depredadores.',
  'senda-gigante': 'Titanes furiosos que crecen en tamaño y poder para igualar a las criaturas más grandes del mundo. Gastan su Furia para aumentar su alcance, imbuir sus armas con elementos puros y lanzar objetos inmensos. Cumplen el rol de artillería pesada y control territorial, brillando al arrojar a los enemigos por los aires y golpear a gran distancia con fuerza colosal imparable.',
  'senda-heraldo-tormenta': 'Guerreros elementales que desatan la furia climática de los desiertos, mares o tundras sobre el enemigo. Consumen su Furia para irradiar auras que queman, electrocutan o congelan a todo el que se acerca. Actúan como controladores de área, brillando al dañar automáticamente a grupos de enemigos y otorgar resistencia elemental a sus compañeros de aventuras cercanos.',
  'senda-magia-salvaje': 'Conductos inestables de magia arcana que liberan su poder con cada arranque de ira. Utilizan su Furia para detonar efectos aleatorios que pueden curar, dañar o alterar el espacio a su alrededor. Cumplen el rol de guerreros impredecibles y apoyo mágico, brillando al devolver hechizos enemigos y potenciar las habilidades místicas y defensivas de todo su grupo.',
  'guardian-espiritual': 'Centinelas guiados por ancestros que entrelazan la ofensiva letal con una defensa mística constante. Gastan su Furia para manifestar espíritus que reducen el impacto enemigo y asedian a sus presas. Actúan como escudos vivientes y castigadores, brillando al desviar daño masivo y garantizar que los ataques más letales se vuelvan en contra de los propios agresores.',
  'path-of-lament': 'Almas atormentadas que canalizan su profundo dolor en una fuerza destructiva que marchita a los vivos. Gastan su Furia para emitir lamentos sobrenaturales que paralizan de terror y debilitan el cuerpo del enemigo. Cumplen el rol de vanguardia disruptiva, brillando al reducir la resistencia de las criaturas más temibles y empoderarse temporalmente con la no muerte.',
  'path-of-unlight': 'Portadores de una radiación profana que quema la cordura y el cuerpo con una luz destructiva. Utilizan su Furia para cegar a los agresores cercanos y desatar explosiones radiantes con cada golpe brutal. Operan como atacantes de desgaste territorial, brillando al castigar automáticamente los ataques enemigos y envolver el campo de batalla en una luminosidad letal y cegadora.',
  'colegio-conocimiento': 'Eruditos curiosos que acumulan secretos arcanos y tácticas de todas las disciplinas existentes. Gastan su Inspiración Bárdica para frustrar los ataques y pruebas de los enemigos mediante insultos precisos. Actúan como el soporte definitivo y lanzadores versátiles, brillando al acceder a conjuros de cualquier clase y neutralizar los mejores golpes del oponente en el acto.',
  'colegio-valor': 'Historiadores marciales que entonan cantos de guerra en la vanguardia para infundir valor a su grupo. Utilizan su Inspiración Bárdica para sumar daño o defensa a los ataques de sus compañeros. Cumplen el rol de combatientes de apoyo, brillando al combinar ataques con armas y el lanzamiento de conjuros, resistiendo en la primera línea junto a los guerreros más duros.',
  'colegio-glamour': 'Artistas feéricos que tejen magia de encanto para embelesar al público y comandar el campo de batalla. Gastan su Inspiración Bárdica para otorgar velocidad y resistencia a sus aliados con una simple mirada. Operan como líderes tácticos y manipuladores sociales, brillando al reposicionar a todo el equipo sin sufrir daño y forzar a los enemigos a acatar sus órdenes reales.',
  'colegio-danza': 'Acróbatas gráciles que transforman el esquive y el movimiento fluido en un arte marcial letal. Gastan su Inspiración Bárdica para golpear sin armas tras lanzar hechizos y reposicionar a sus aliados en un instante. Actúan como escaramuzadores evasivos, brillando al liderar la iniciativa del grupo y evitar casi todo el daño mediante reflejos y bailes impredecibles.',
  'colegio-luna': 'Místicos conectados con las mareas y el poder primigenio de la noche y el bosque. Utilizan su Inspiración Bárdica para otorgar curación adicional y revitalizar a los aliados más exhaustos. Cumplen el rol de sanadores híbridos, brillando al desatar rayos de luz lunar sobre los monstruos y proteger a su equipo bajo el manto ilusorio y seguro del crepúsculo.',
  'colegio-espiritus': 'Narradores esotéricos que invocan los relatos de héroes muertos para alterar el curso de la historia. Gastan su Inspiración Bárdica para canalizar efectos aleatorios poderosos a través de una baraja o calavera. Actúan como lanzadores de apoyo impredecibles, brillando al sanar o dañar con explosiones místicas y contactar con el más allá en busca de respuestas cruciales.',
  'colegio-creacion': 'Compositores de la canción primordial que materializan objetos de la nada con pura voluntad. Consumen su Inspiración Bárdica para crear notas místicas que potencian a los aliados según la acción que realicen. Operan como manipuladores del entorno, brillando al animar estatuas o muebles para luchar por ellos y forjar equipamiento perfecto en el momento que más se necesita.',
  'colegio-elocuencia': 'Oradores persuasivos cuyas palabras son leyes absolutas y cuyas mentiras son verdades incuestionables. Gastan su Inspiración Bárdica para mermar severamente las defensas mágicas del enemigo. Cumplen el rol de diplomáticos imbatibles y controladores, brillando al asegurar que sus aliados nunca desperdicien la inspiración y al doblegar multitudes enteras con un discurso.',
  'colegio-espadas': 'Artistas del filo que convierten los duelos mortales en un espectáculo deslumbrante de acrobacias. Utilizan su Inspiración Bárdica para realizar florituras letales que aumentan su defensa, movilidad o daño de área. Actúan como combatientes cuerpo a cuerpo evasivos, brillando al deslizarse entre los oponentes y diezmar las líneas enemigas con una velocidad abrumadora.',
  'colegio-susurros': 'Espías siniestros que emplean las palabras para sembrar paranoia, dolor psíquico y terror absoluto. Gastan su Inspiración Bárdica para infundir sus armas con magia letal que desgarra la mente. Operan como asesinos sociales y atacantes de ráfaga, brillando al robar la apariencia y secretos de los muertos para infiltrarse en las cortes más seguras sin levantar sospechas.',
  'no-muerto': 'Siervos de una entidad que conquistó la muerte, infundidos con poder necromántico y terror paralizante. Gastan su magia para asumir una forma macabra que aterroriza a los enemigos cercanos y los hace resistentes. Operan como controladores defensivos, brillando al proyectar un aura de miedo que rompe formaciones enemigas y al negarse a morir, curándose con su daño oscuro.',
  'filo-maldito': 'Combatientes oscuros ligados a armas arcanas sedientas de almas y maldiciones. Utilizan su destreza mágica para golpear con Carisma y señalar a sus enemigos con un maleficio letal e ineludible. Actúan como asaltantes cuerpo a cuerpo, brillando al diezmar blancos prioritarios con daño masivo, alzando los espíritus de sus víctimas caídas para que luchen por su causa.',
  'genio': 'Agentes de señores elementales nobles que canalizan la furia de los elementos y el ingenio de los deseos. Gastan su poder para desatar daño elemental adicional y refugiarse mágicamente en un recipiente místico portátil. Operan como artillería mágica evasiva, brillando al volar por el campo de batalla, otorgar resistencia a su grupo y descansar seguros en cualquier entorno.',
  'inmortal': 'Pactantes de un ser que domina la longevidad, renunciando a las debilidades físicas para burlar la muerte. Gastan su magia para curarse al estar al borde del colapso o al estabilizar a compañeros heridos. Actúan como lanzadores resistentes, brillando en campañas de supervivencia extrema, donde su inmunidad a la vejez, las enfermedades y la asfixia los hace imparables.',
  'sorcerer-king-patron': 'Heraldos de tiranos psiónicos que imponen un yugo mental sobre el campo de batalla para doblegar voluntades. Consumen espacios mágicos para castigar a quienes los atacan y aplastar los escudos mentales del enemigo. Operan como controladores opresivos, brillando al forzar a múltiples criaturas a postrarse o huir, utilizando magia coercitiva absoluta para someter a multitudes.',
  'primordial-patron': 'Sirvientes del caos elemental puro que preparan el terreno para el regreso de poderes titánicos destructivos. Utilizan su poder para crear nodos de energía que fortalecen a los suyos y vulneran a las fuerzas enemigas. Cumplen el rol de estrategas de área, brillando al anclar el combate en sus zonas de tormenta o magma, resistiendo ataques mientras desencadenan cataclismos.',
  'cazafantasmas': 'Exorcistas marciales que empuñan la luz pura para purgar el mundo de espíritus malignos y muertos vivientes. Utilizan su sangre para imbuir sus armas con fulgor radiante y atravesar barreras etéreas sin esfuerzo. Operan como cazadores de precisión, brillando al desmantelar las resistencias de las entidades oscuras y separar su alma del cuerpo para seguir peleando si caen.',
  'licantropo': 'Bestias controladas que abrazan la maldición para obtener una fuerza salvaje y sentidos sobrenaturales en combate. Gastan su acción para transformarse en híbridos letales que regeneran heridas y atacan con garras. Cumplen el rol de combatientes de vanguardia resistentes, brillando al desatar ráfagas de ataques cuerpo a cuerpo y resistir daño masivo gracias a su gruesa piel.',
  'mutante': 'Alquimistas de la biología que ingieren tóxicos inestables para potenciar sus atributos más allá del límite. Consumen brebajes para volverse veloces, letales o inmunes, adaptándose a cada cacería específica. Actúan como guerreros hiperespecializados, brillando al purgar toxinas dañinas de su cuerpo rápidamente y anular mágicamente las defensas biológicas de sus presas.',
  'alma-profana': 'Inquisidores que negocian con los poderes del mal para asegurar victorias que las armas mundanas no logran. Gastan espacios de pacto arcanos para combinar ataques marciales con trucos destructivos. Operan como guerreros mágicos híbridos, brillando al encadenar a los enemigos a su voluntad y desatar conjuros mayores para sorprender a presas que no esperan ataques místicos.',
  'dominio-vida': 'Sacerdotes consagrados a la preservación absoluta, perfeccionando el arte de la medicina espiritual. Consumen espacios de conjuro para sanar más que cualquier otra disciplina, potenciando cada cura. Cumplen el rol definitivo de apoyo vital, brillando al levantar a todo el grupo del borde de la muerte de un solo golpe, maximizando cada curación sin desperdiciar recursos.',
  'dominio-luz': 'Devotos del amanecer que esgrimen fuego purificador para barrer a las huestes de la oscuridad. Gastan usos de su divinidad para emitir destellos que ciegan atacantes y disipar sombras arcanas al instante. Operan como artillería mágica y defensores reactivos, brillando al incinerar hordas enteras con luz sagrada y proteger a sus aliados cegando a los monstruos en combate.',
  'dominio-engano': 'Ilusionistas divinos que sirven a deidades caóticas, sembrando la duda y la confusión por doquier. Utilizan su canalización para crear copias perfectas de sí mismos, engañando ataques y lanzando magia desde lejos. Actúan como infiltradores y controladores, brillando al otorgar sigilo a los aliados pesados y teletransportarse a un lugar seguro en medio de la confusión general.',
  'dominio-guerra': 'Capellanes militares acorazados que lideran las cargas más brutales con precisión divina inquebrantable. Gastan su poder sagrado para asegurar impactos cruciales o desatar ataques extra en momentos desesperados. Cumplen el rol de vanguardia híbrida, brillando al bendecir a sus guerreros más letales y mantener una defensa impenetrable mientras asestan golpes críticos.',
  'dominio-conocimiento': 'Eruditos sagrados que leen la historia de los objetos y las mentes de los seres que se cruzan en su camino. Consumen magia para hablar cualquier idioma o dominar habilidades de forma instantánea al necesitarlas. Actúan como apoyo social y utilidad, brillando al desentrañar los secretos más oscuros de la campaña y leer los pensamientos enemigos para evitar emboscadas mortales.',
  'dominio-tumba': 'Custodios de la frontera final que aborrecen a los muertos vivientes y mantienen a los suyos en este mundo. Gastan su poder para maldecir a un enemigo, haciéndolo vulnerable a un golpe masivo y destructivo. Operan como sanadores de emergencia, brillando al salvar aliados caídos con magia maximizada y anular los golpes críticos del enemigo para proteger la frágil vida.',
  'dominio-arcano': 'Iniciados en los misterios de la magia pura que combinan la fe con el estudio riguroso de los grimorios. Utilizan su divinidad para modificar sus hechizos al instante, disipando encantamientos ajenos mientras sanan. Cumplen el rol de controladores mágicos, brillando al castigar a criaturas de otros planos e incorporar los conjuros arcanos más destructivos a su repertorio.',
  'dominio-tempestad': 'Sacerdotes del caos meteorológico que visten acero pesado y dictan la voluntad de las grandes tormentas. Gastan su divinidad para maximizar el daño de rayos y truenos, desatando la aniquilación pura en segundos. Actúan como artillería pesada y represaliadores, brillando al empujar a los atacantes lejos y electrocutar a quienes osan golpearles en pleno combate cuerpo a cuerpo.',
  'dominio-naturaleza': 'Guardianes de la vida salvaje que ordenan a las bestias y plantas luchar bajo su estandarte sagrado. Consumen su energía para pacificar criaturas del bosque y proteger a su equipo de los elementos agresivos. Operan como controladores territoriales, brillando al envolverse en pesadas armaduras mientras desvían ataques elementales letales con la fuerza de los robles antiguos.',
  'dominio-forja': 'Artesanos bendecidos que dedican su vida a perfeccionar la materia, el fuego y las armaduras eternas. Gastan su fe para imbuir acero mundano con magia permanente y crear herramientas perfectas en plena expedición. Cumplen el rol de tanques elementales, brillando al resistir llamaradas directas y elevar la capacidad defensiva de todo el grupo con su obra maestra sagrada.',
  'dominio-orden': 'Jueces severos que imponen estructura en un mundo caótico, doblegando mentes con su simple voz. Utilizan sus hechizos para permitir que sus aliados ataquen de inmediato fuera de su turno normal. Actúan como líderes tácticos, brillando al dictar el flujo de la batalla, obligar a los enemigos a rendir sus armas y asegurar que la justicia se imparta con precisión implacable.',
  'dominio-paz': 'Pacificadores amados que forjan vínculos místicos irrompibles entre sus compañeros de aventuras. Gastan su energía para compartir el daño entre los miembros del grupo y moverse por el caos sanando a todos. Operan como soportes preventivos, brillando al aumentar drásticamente la precisión del equipo y garantizar que ningún aliado perezca mientras los demás sigan en pie luchando.',
  'dominio-crepusculo': 'Centinelas del ocaso que resguardan a los viajeros de los horrores que acechan en las sombras más frías. Utilizan su canalización para desplegar esferas de penumbra que curan el terror y regeneran salud a cada instante. Cumplen el rol de protectores absolutos, brillando al otorgar la mejor visión nocturna posible e infundir iniciativa y coraje antes de que la batalla comience.',
  'dominio-muerte': 'Sacerdotes oscuros que ven el fin como una herramienta necesaria para potenciar su poder necrótico. Gastan su magia para golpear a múltiples enemigos cercanos con hechizos marchitadores ignorando sus defensas. Operan como atacantes mágicos agresivos, brillando al desatar toques de podredumbre letal y asegurar que sus venenos oscuros aniquilen hasta a los más resistentes.',
  'freedom-domain': 'Libertadores sagrados que rechazan cualquier forma de opresión, grillete o subyugación mágica. Utilizan su divinidad para romper encantamientos mentales e inspirar a sus aliados a moverse con libertad absoluta. Cumplen el rol de sanadores de movilidad, brillando al evadir el terreno difícil sin armadura pesada y garantizando que el grupo nunca quede paralizado ante el enemigo.',
  'pestilence-domain': 'Heraldos de la decadencia que ven en las plagas una herramienta para limpiar la debilidad del mundo. Gastan su fe para desatar nubes tóxicas y envenenar con precisión a quienes se interponen en su camino. Actúan como controladores de daño continuo, brillando al debilitar gradualmente las líneas enemigas y al convertirse en enjambres imposibles de inmovilizar o erradicar.',
  'circulo-tierra': 'Guardianes de los paisajes fundamentales que extraen poder arcano de la esencia misma del bioma. Gastan usos de su magia para sanar o dañar con la vitalidad del suelo, recuperando conjuros sin descansar largo rato. Operan como magos de utilidad, brillando al adaptar su repertorio mágico al clima del día y moverse por obstáculos naturales sin dejar rastro ni sufrir retrasos.',
  'circulo-luna': 'Fieros defensores que renuncian a la humanidad para luchar bajo la forma de bestias colosales y letales. Gastan su transformación primigenia no para espiar, sino para devorar, golpear y resistir daño masivo. Cumplen el rol de combatientes cuerpo a cuerpo, brillando al lanzar conjuros desde formas animales duras y bañar sus colmillos con luz sagrada destructora e imparable.',
  'circulo-estrellas': 'Videntes cósmicos que leen los misterios del universo para adoptar formas astrales resplandecientes. Gastan su poder salvaje para convertirse en constelaciones vivientes que curan, disparan luz o aseguran hechizos. Operan como artillería mágica y sanadores, brillando al predecir el futuro para alterar tiradas y mantenerse levitando lejos del peligro mientras atacan.',
  'circulo-suenos': 'Emisarios de las cortes feéricas que caminan entre los mundos para proteger el descanso y curar el dolor. Gastan un pozo de energía mística para sanar aliados rápidamente sin consumir sus espacios de hechizos valiosos. Cumplen un rol de sanadores y guardianes, brillando al crear refugios invisibles seguros para dormir y teletransportarse a voluntad por el campo de batalla.',
  'circulo-pastor': 'Protectores de las criaturas más vulnerables, capaces de hablar con cada bestia del gran bosque verde. Consumen su energía para invocar tótems espirituales que fortalecen a los animales que llaman al combate. Operan como invocadores estratégicos, brillando al abrumar al enemigo con decenas de aliados mágicos, manteniéndolos vivos y letales mediante auras de curación masiva.',
  'circulo-esporas': 'Vigilantes de la descomposición que consideran a la muerte como un paso natural hacia una nueva vida. Utilizan su poder para envolverse en esporas mortales que dañan al contacto y levantan sirvientes fúngicos. Cumplen el rol de combatientes híbridos, brillando al generar toneladas de vida temporal y abrumar a las fuerzas enemigas con zombis creados en el fragor de la pelea.',
  'circulo-fuego': 'Sanadores radicales que entienden que a veces la destrucción total es el único camino hacia el renacimiento. Gastan su magia para invocar espíritus ardientes que incineran rivales y curan heridas en un parpadeo. Actúan como atacantes a distancia móviles, brillando al teletransportar a sus aliados a través de llamas explosivas y revivir a los caídos con el calor primordial.',
  'circle-of-preservation': 'Restauradores de la vida que buscan purificar las tierras corruptas y sellar el mal en su interior. Utilizan su magia para fortificar zonas del suelo, otorgando ventajas masivas a quienes se paran sobre ellas. Cumplen el rol de defensores de área, brillando al limpiar el veneno, disipar maldiciones rápidamente y mantener al grupo intacto frente a los horrores ambientales.',
  'circle-of-the-titan': 'Colosos de la naturaleza furiosa que adoptan formas gargantuescas para pisotear a los corruptores. Gastan su transformación para asumir tamaños abrumadores, rompiendo defensas mágicas con pura fuerza bruta. Operan como rompelíneas masivos, brillando al causar daños estructurales inmensos, devorar magia débil y atraer el fuego de todos los oponentes del campo a su cuerpo.',
  'esporas-playtest': 'Vigilantes de la descomposición que tejen redes místicas mediante halos venenosos indetectables a simple vista. Gastan su poder para infestarse a sí mismos, endureciendo su carne para combatir en primera fila sin caer. Actúan como tanques nigrománticos, brillando al hacer explotar cadáveres en medio de los enemigos y levantar escudos fúngicos para aguantar castigos mortales.',
  'bestias': 'Exploradores vinculados en cuerpo y alma a un compañero primigenio que crece y caza a su lado. Gastan su concentración para lanzar magia que afecta tanto a sí mismos como a su bestia, duplicando la letalidad. Operan como flanqueadores perfectos, brillando al abrumar enemigos con múltiples ataques coordinados, convirtiendo a su mascota en una fuerza letal en plena batalla.',
  'hadas': 'Maestros del engaño forestal que emplean magia feérica ilusoria para aterrorizar y distraer al oponente. Utilizan sus encantamientos para castigar mentalmente a los rivales e invocar refuerzos mágicos de la nada. Cumplen el rol de atacantes de control, brillando al evitar la manipulación enemiga y asegurar tratos sociales perfectos gracias a su carisma potenciado misticamente.',
  'sombras': 'Asesinos de la oscuridad que castigan a quienes dependen de la luz, invisibles incluso para la magia. Gastan su primer turno para desatar una ráfaga de ataques devastadores con una agilidad inigualable y letal. Actúan como eliminadores de objetivos, brillando al emboscar al grupo enemigo sin ser detectados y resistiendo efectos mentales gracias a su férrea disciplina de hierro.',
  'guardian-hueco': 'Caminantes de las pesadillas que adoptan formas grotescas para devorar el miedo de sus adversarios. Utilizan su magia para infligir terror e impedir que los monstruos asustados huyan o logren curarse. Cumplen el rol de asaltantes aterradores, brillando al recuperar salud devorando la esencia de sus presas y volverse imparables contra aquellos que sucumben ante su presencia.',
  'cazador': 'Estrategas de la supervivencia que analizan las formaciones enemigas para exterminar hordas rápidamente. Consumen su astucia para resistir golpes letales y golpear a múltiples objetivos agrupados en un solo movimiento. Operan como combatientes adaptables, brillando al identificar la inmunidad de su presa y evadir ataques de monstruos colosales con giros defensivos precisos.',
  'caminante-invierno': 'Acechadores del páramo helado que congelan el avance enemigo con hielo mágico y frío cortante. Gastan su magia para invocar armaduras de escarcha y ralentizar a sus presas con cada ataque certero. Actúan como controladores de movilidad, brillando al sanar a los aliados con magia revitalizante e inutilizar a los rivales congelando sus extremidades si se atreven a golpearlos.',
  'guardian-draconico': 'Jinetes vinculados a un aliado místico escamado que comparte su dolor y desata alientos elementales. Utilizan sus órdenes tácticas para volar sobre el campo de batalla montados en un draco imponente. Cumplen el rol de caballería pesada y apoyo móvil, brillando al combinar ataques de armas con explosiones de ácido o fuego, protegiéndose mutuamente de daños mágicos letales.',
  'caminante-horizonte': 'Centinelas del espacio y el tiempo que cruzan portales invisibles para proteger el plano material. Gastan su magia para convertir sus ataques en fuerza pura y hacerse intocables caminando por el éter oscuro. Operan como atacantes esquivos, brillando al teletransportarse antes de cada golpe, conectando ataques múltiples imposibles de predecir o detener por defensas físicas.',
  'cazador-monstruos': 'Eruditos letales especializados en aniquilar aberraciones, vampiros y hechiceros oscuros. Utilizan su conocimiento instintivo para frustrar huidas, teletransportes y rituales mágicos con rapidez letal. Cumplen el rol de duelistas de élite, brillando al resistir los encantamientos de su presa y devolver conjuros fatales a los lanzadores enemigos con contraataques precisos.',
  'guardian-enjambre': 'Exploradores envueltos por miles de espíritus minúsculos que empujan, pican y desvían la atención. Gastan su voluntad para ordenar al enjambre que los levante por los aires o ciegue a sus atacantes cercanos. Actúan como controladores tácticos, brillando al mover enemigos a zonas peligrosas, evitar daño desvaneciéndose en insectos y volar sobre el caos de la guerra.',
  'arquero-arcano': 'Tiradores de precisión que fusionan la arquería élfica con la versatilidad de la magia evocadora más letal. Gastan sus flechas imbuidas para desatar efectos explosivos, cegar enemigos o enredarlos en zarzas mortales. Operan como francotiradores de utilidad, brillando al desviar mágicamente disparos fallidos hacia otros blancos y resolver rompecabezas a largas distancias.',
  'caballero-dragon-purpura': 'Capitanes de guerra de gran carisma que inspiran hazañas heroicas en medio del caos de la batalla. Utilizan sus capacidades curativas y su impulso de acción para extender sus beneficios a todos los aliados cercanos. Cumplen el rol de líderes de vanguardia, brillando al permitir que su equipo reaccione fuera de turno, asestando golpes adicionales o superando pruebas mortales.',
  'maestro-batalla': 'Tácticos brillantes que estudian el flujo del combate como una intrincada partida de ajedrez sangrienta. Gastan sus dados de superioridad para desarmar, empujar, distraer o contraatacar al enemigo con precisión de cirujano. Operan como duelistas de control absoluto, brillando al analizar las debilidades del rival y adaptar sus maniobras físicas a cualquier situación.',
  'campeon': 'Atletas perfeccionados que confían únicamente en su fuerza física, velocidad y resistencia sin igual. No gastan recursos mágicos, dependiendo de su capacidad pasiva para asestar golpes críticos con temible regularidad. Actúan como atacantes sostenidos, brillando en largas campañas de desgaste, donde su agilidad constante y regeneración pasiva los hacen imposibles de detener.',
  'caballero-arcano': 'Guerreros místicos que tejen abjuraciones y explosiones entre los letales giros de su espada pesada. Consumen espacios de conjuro para protegerse con magia rápida mientras destrozan al enemigo en el frente. Cumplen el rol de tanques mágicos, brillando al combinar trucos arcanos con ataques físicos en un solo movimiento fluido, volviéndose inalcanzables gracias a su teletransporte.',
  'guerrero-psionico': 'Combatientes iluminados que aumentan su destreza física con potentes ráfagas de poder mental puro. Gastan dados psiónicos para reducir daño, empujar colosos o saltar distancias increíbles sin esfuerzo. Operan como atacantes de movilidad táctica, brillando al mover objetos y criaturas telepáticamente y proteger a los caídos con escudos invisibles de fuerza inquebrantable.',
  'caballero': 'Jinetes acorazados que protegen a los débiles y se interponen entre el peligro y sus compañeros heridos. Utilizan sus tácticas defensivas para marcar al enemigo, castigándolo severamente si ataca a otro blanco. Actúan como escoltas y defensores frontales, brillando al controlar el territorio, impidiendo que nadie huya o pase a través de su infranqueable barrera de acero puro.',
  'caballero-eco': 'Manipuladores del tiempo que atraen versiones de sí mismos desde otras líneas temporales posibles. Gastan su energía para atacar desde posiciones ilusorias, intercambiando lugares para confundir ataques mortales. Cumplen el rol de flanqueadores supremos, brillando al atacar zonas múltiples sin riesgo físico y absorber daño masivo sacrificando a sus clones espectrales eternos.',
  'samurai': 'Guerreros de determinación absoluta que se niegan a rendirse ante el cansancio o las heridas fatales. Utilizan su espíritu inquebrantable para golpear con ventaja, obteniendo barreras temporales de pura voluntad férrea. Operan como atacantes de daño masivo sostenido, brillando al convencer diplomáticamente en las cortes y al retrasar su propia muerte para asestar un último golpe letal.',
  'caballero-runico': 'Guardianes de la sabiduría antigua que inscriben secretos de los gigantes en sus armas y armaduras. Gastan su poder rúnico para alterar la suerte de los dados, prender fuego a sus presas o invocar cadenas etéreas. Actúan como tanques de control híbrido, brillando al aumentar a tamaños colosales y someter a criaturas enormes que de otro modo destruirían al grupo entero fácilmente.',
  'caballero-playtest': 'Defensores implacables que se erigen como muros inexpugnables entre las bestias y sus aliados frágiles. Utilizan sus reacciones para interceptar golpes y castigar a quienes ignoran sus desafíos territoriales absolutos. Cumplen el rol de guardianes de primera fila, brillando al dominar las monturas de guerra y asegurar que ningún enemigo logre cruzar su área de amenaza ileso.',
  'gladiator': 'Estrellas de la arena que deslumbran al público mientras destrozan sistemáticamente a sus rivales. Gastan su maestría táctica en encadenar maniobras brutales que mutilan, derriban y humillan al oponente en un instante. Operan como asaltantes de control, brillando al aprovechar acrobacias para golpear con florituras y sanar sus propias heridas absorbiendo el aplauso de la multitud.',
  'hell-knight': 'Campeones infernales forjados en las brasas del Averno que esparcen agonía y desesperación pura. Utilizan fuego oscuro para imbuir sus armas y dejar heridas supurantes que debilitan progresivamente al enemigo. Actúan como combatientes de desgaste letal, brillando al mermar la vitalidad de sus presas y resistir climas mortales gracias a la bendición de los archidiablos sombríos.',
  'aberrante': 'Hechiceros marcados por el Lejano Reino, dotados con una mente capaz de someter la voluntad del multiverso. Gastan su magia y puntos para hablar telepáticamente y eludir componentes vocales para conjuros indetectables. Operan como controladores mentales, brillando al volar, volverse gelatinosos para escapar de cadenas y desatar horrores invisibles desde las sombras más espesas.',
  'reloj': 'Emisarios del orden puro de Mechanus que imponen fórmulas matemáticas precisas al caos de la realidad. Utilizan su poder para neutralizar ventajas enemigas y proteger a los aliados con barreras geométricas de fuerza. Cumplen el rol de defensores mágicos, brillando al equilibrar el campo de batalla, asegurando resultados estables en los dados y evitando fallos críticos letales.',
  'alma-divina': 'Bendecidos con magia celestial pura que fluye por sus venas sin depender de juramentos ni deidades. Gastan puntos de hechicería para potenciar curaciones milagrosas y esquivar su destino en los momentos críticos. Actúan como sanadores tácticos y atacantes, brillando al mezclar la versatilidad de los clérigos con la metamagia destructiva de los hechiceros en plena guerra mística.',
  'lunar': 'Hechiceros vinculados a las fases de la luna, cambiando de forma mágica según las necesidades del combate. Utilizan su magia fluida para intercalar entre luz purificadora, sombras tóxicas y poder psíquico abrumador. Operan como lanzadores hiperversátiles, brillando al reducir costes de metamagia en su fase afín y sanar aliados mientras queman demonios bajo el rayo nocturno puro.',
  'hechiceria-sombras': 'Conductos lúgubres del Páramo Sombrío, envueltos en penumbra e ilusiones terroríficas inescrutables. Gastan sus puntos mágicos para invocar horrores caninos espectrales que acosan sin piedad a los oponentes heridos. Cumplen el rol de infiltradores y asesinos mágicos, brillando al ver en la negrura mágica que ellos mismos crean y al negarse a morir gracias a su voluntad impía.',
  'fuego-conjuro': 'Devoradores de magia pura que canalizan las llamas primordiales para castigar y purificar simultáneamente. Utilizan su dominio arcano para anular conjuros enemigos y absorber esa energía para su propio beneficio ofensivo. Actúan como artillería defensiva letal, brillando al curar y quemar con cada hechizo lanzado, volando rodeados de fuego abrasador indestructible en el cielo.',
  'tormenta': 'Gobernantes de los vientos y los truenos que se deslizan por el campo de batalla envueltos en relámpagos puros. Gastan su hechicería para volar pequeñas distancias sin sufrir ataques de oportunidad con cada conjuro ofensivo. Operan como escaramuzadores mágicos ágiles, brillando al golpear a grupos de enemigos con daño sónico pasivo y al calmar las tormentas climáticas más violentas.',
  'defiled-sorcery': 'Lanzadores corruptos que absorben la vitalidad del mundo a su alrededor para potenciar sus actos ruines. Utilizan su poder marchitador para envenenar auras y robar puntos de golpe a quienes se atreven a acercarse mucho. Cumplen el rol de atacantes de desgaste necrótico, brillando al volverse inmunes a las toxinas y desgastar lentamente escuadrones enteros con emanaciones oscuras.',
  'demonic-sorcery': 'Agentes del caos abisal que rasgan la estructura de la realidad para invocar horrores insondables directos. Gastan su magia para abrir rupturas destructivas que enloquecen e incineran a cualquier criatura atrapada allí. Actúan como artillería de daño expansivo, brillando al lanzar explosiones demoníacas inmensas y resistir golpes mortales devolviendo la energía destructiva pura.',
  'faerzress-sorcery': 'Hechiceros irradiados por la magia subterránea letal que emplean esta energía para burlar leyes arcanas. Utilizan puntos mágicos para desatar zonas de radiación que frustran adivinaciones y ciegan a sus enemigos letales. Operan como saboteadores místicos, brillando al teletransportarse mediante el caos y envenenar con locura a cualquiera que falle en resistir sus asaltos de rayo.',
  'ancestral-sorcery': 'Médium arcanos guiados por el intelecto fantasmal de sus predecesores, combinando magia y memoria antigua. Gastan su poder para desbaratar conjuros enemigos antes de que sucedan y dominar mentalmente a sus agresores. Cumplen el rol de controladores puros, brillando al anular ilusiones fácilmente y volverse impenetrables para quienes intentan romper su sagrada concentración mística.',
  'abjuracion': 'Eruditos de la protección suprema que dedican su vida a anular los asaltos físicos y místicos de los villanos. Utilizan sus conocimientos para alimentar campos de fuerza arcanos que absorben el castigo destinado a su equipo. Actúan como defensores antimagia inquebrantables, brillando al resistir conjuros con facilidad pasmosa y aplastar encantamientos ajenos antes de que existan.',
  'cantor-hoja': 'Espadachines místicos que danzan en primera línea combinando esgrima letal con magia devastadora de cerca. Gastan su tiempo en un trance veloz que dispara su armadura y velocidad a niveles imposibles de alcanzar. Operan como combatientes híbridos ágiles, brillando al lanzar explosiones y estocadas en el mismo instante, mitigando heridas fatales con puros cánticos defensivos antiguos.',
  'conjuracion': 'Maestros de las dimensiones que alteran la geografía del campo de batalla y traen siervos de otros planos oscuros. Utilizan su magia para intercambiar posiciones instantáneas, eludiendo trampas y rescatando amigos perdidos. Cumplen un rol de soporte de movilidad, brillando al asegurar que sus invocaciones perduren golpes brutales sin romper nunca la concentración del hechicero sutil.',
  'adivinacion': 'Videntes que han desentrañado las hebras del destino, alterando los caprichos del azar a su conveniencia. Gastan sus portentosos sueños para predefinir el resultado de los dados, salvando aliados o condenando enemigos. Actúan como controladores absolutos de la suerte, brillando al recuperar magia tras cada visión profunda y ver con claridad ilusiones místicas, oscuridad y lo invisible.',
  'encantamiento': 'Manipuladores de corazones y mentes que dictan las pasiones y lealtades de cualquier criatura en su camino. Utilizan miradas hipnóticas para incapacitar rivales y desviar ataques mortales hacia otros monstruos. Operan como controladores sociales y de batalla, brillando al extender un mismo hechizo mental a múltiples víctimas, alterando sus recuerdos para evitar las crueles represalias.',
  'evocacion': 'Conductos de destrucción masiva que moldean el fuego, el hielo y los relámpagos con precisión quirúrgica pura. Gastan su astucia para esculpir sus explosiones devastadoras, evitando dañar a sus aliados en el fuego cruzado letal. Cumplen el rol de artillería pesada garantizada, brillando al asestar daño incluso cuando el enemigo evade el golpe, maximizando la aniquilación de la zona.',
  'ilusion': 'Engañadores sublimes que convierten la luz, el sonido y la percepción en herramientas de dominación perfecta. Utilizan su imaginación para modificar fantasmas y volver sólidas sus mentiras si la situación lo requiere rápido. Actúan como saboteadores defensivos supremos, brillando al esquivar ataques escondidos tras dobles perfectos y resolver obstáculos volviendo reales los puros sueños.',
  'necromancia': 'Amos del ciclo de la carne que estudian la energía oscura para comandar formidables ejércitos silenciosos. Gastan su fuerza para reanimar muertos vivientes potenciados, nutriéndose de la energía vital al matar a alguien. Operan como líderes de escuadrón oscuros, brillando al resistir daño necrótico letal y abrumar las líneas enemigas explotando las almas puras de sus siervos caídos.',
  'transmutacion': 'Alquimistas de la materia prima que alteran los atributos físicos de los objetos y cuerpos con gran facilidad. Utilizan piedras filosóficas portátiles para otorgar resistencia, velocidad o sentidos agudos a sus compañeros leales. Cumplen el rol de utilidad versátil continua, brillando al curar enfermedades raras con un toque y transformar materiales mundanos en defensas valiosas y útiles.',
  'magia-cronurgia': 'Manipuladores de la línea temporal que pausan y aceleran el flujo del combate con un pensamiento preciso. Gastan sus conocimientos para encerrar hechizos destructivos en perlas mágicas o detener enemigos en estasis. Actúan como estrategas de control, brillando al dictar la iniciativa del grupo y forzar resultados de dados a costa de su propia salud física desgastada e inestable.',
  'magia-graviturgia': 'Controladores de la densidad que juegan con el peso del mundo para inmovilizar o acelerar a voluntad plena. Utilizan campos gravitacionales para empujar, lanzar armas con más fuerza o aplastar a quienes huyen de su zona. Operan como controladores territoriales, brillando al impedir que enemigos veloces escapen, manteniéndolos pegados al suelo bajo el peso de mil soles invisibles oscuros.',
  'escribas': 'Amantes de la tinta y el papel que logran despertar la verdadera conciencia dormida de su grimorio personal arcano. Gastan su mente en lanzar magia a través del libro, intercambiando los tipos de daño mágico a voluntad y necesidad. Actúan como magos de asalto seguros, brillando al escribir pergaminos en tiempo récord y absorber daño letal sacrificando partes de su vasto conocimiento puro.',
  'magia-guerra': 'Veteranos blindados de las trincheras arcanas que fusionan reflejos rápidos con defensas impenetrables fuertes. Utilizan su concentración para aumentar su armadura al máximo y absorber energía enemiga al contrarrestar los conjuros. Cumplen el rol de combatientes defensivos ágiles, brillando al desviar ataques mortales hacia sus adversarios en explosiones potentes de relámpago salvaje.',
  'imaskarcanist': 'Buscadores de reliquias perdidas que manipulan energías extrañas para curar y destruir simultáneamente todo. Gastan dados de magia corrupta para alterar hechizos de fuego en energía radiante sanadora o maldita a la vez. Operan como magos de daño versátil, brillando al revitalizar aliados gravemente heridos usando el mismo fuego mágico destructivo que asedia a sus desesperados rivales.',
  'misericordia': 'Sanadores enmascarados del campo de batalla que deciden quién vive para luchar y quién muere en la oscuridad. Gastan Puntos de Enfoque para sanar instantáneamente tocando heridas o inyectar necrosis directamente en la sangre enemiga. Actúan como soportes híbridos letales, brillando al resucitar aliados caídos y envenenar brutalmente a blancos con una simple ráfaga veloz de golpes curativos y mortales.',
  'elementos': 'Canalizadores ágiles de la furia cósmica que dominan las fuerzas del magma, la nieve y las tormentas bravas. Utilizan su ki interior para alargar el alcance de sus golpes, desatando feroces explosiones de área al atacar de cerca. Cumplen el rol de atacantes de zona y control, brillando al volar velozmente sobre los peligros del suelo y evadir los daños elementales directos con pasmosa facilidad.',
  'artes-misticas': 'Combatientes que entrelazan la disciplina marcial con hechizos destructivos para desarmar y aniquilar grupos. Gastan espacios de conjuro para recargar su energía mística, golpeando con fuego o hielo en medio de sus ráfagas letales. Operan como escaramuzadores mágicos impredecibles, brillando al castigar debilidades elementales rápidamente y mantener la ofensiva continua sin agotar todos sus recursos.',
  'dragon-ascendente': 'Acróbatas imbuidos del poder de los dragones antiguos que canalizan la furia alada de estos en cada golpe preciso. Gastan su concentración para lanzar poderosos alientos, volar espectralmente y aterrorizar a los enemigos cercanos. Actúan como combatientes de control móvil, brillando al rodear a sus aliados con auras protectoras dracónicas y ver en la más absoluta de las cegadoras oscuridades.',
  'yo-astral': 'Contemplativos silenciosos que extraen su espíritu puro para luchar con múltiples brazos de energía dorada. Utilizan su enfoque para invocar máscaras y cuerpos espectrales que desvían daño físico y golpean con la mente limpia. Cumplen el rol de tanques evasivos defensivos, brillando al atacar desde la seguridad de la distancia y usar su carisma y sabiduría sobrenatural para dominar diálogos tensos.',
  'maestro-borracho': 'Maestros del fingimiento que emplean movimientos erráticos y tambaleantes para desarmar la guardia enemiga seria. Gastan su energía en escabullirse de situaciones rodeadas, redirigiendo los ataques enemigos hacia sus propios aliados oscuros. Operan como hostigadores de grandes multitudes, brillando al eludir el peligro constante y asestar múltiples ráfagas a distintos blancos sin jamás quedarse quietos.',
  'kensei': 'Artistas de las armas blancas que fusionan su disciplina espiritual con filos mortales para cortes perfectos y precisos. Utilizan su concentración para aumentar el daño, afilar sus espadas o disparar flechas de daño sobrenatural a gran distancia. Actúan como duelistas físicos, brillando al eludir daño parando golpes brutales e ignorando las defensas naturales de monstruos y demonios acorazados.',
  'larga-muerte': 'Monjes macabros que estudian meticulosamente el tránsito final, alimentándose del terror de los caídos en combate. Gastan su ki para asustar masivamente y negarse a morir, aferrándose a la vida en el momento de recibir golpes mortales y directos. Cumplen el rol de tanques aterradores, brillando al ganar resistencia de forma sostenida e infligir descomunal daño necrótico directo al corazón del enemigo.',
  'alma-solar': 'Guardianes purificadores que convierten su energía vital interna en deslumbrantes esferas de luz sagrada cortante. Gastan su enfoque para desatar conos de llamas ardientes y potentes explosiones brillantes a distancias que el monje no suele alcanzar. Operan como artillería radiante veloz, brillando al rodear su propio cuerpo en halos dañinos y quemando a hordas enteras desde lugares completamente seguros.',
  'embriaguez': 'Especialistas en brebajes arcanos que consumen mezclas inestables para aumentar su resistencia y letalidad rápidamente. Utilizan su sabiduría etílica para levantarse fácil del suelo, lanzar fuego y resistir magia hostil y destructiva. Actúan como combatientes de escaramuza resistentes, brillando al moverse velozmente entre líneas enemigas sin riesgo mientras sus brebajes potencian su agresividad innata.',
  'tattooed-warrior': 'Luchadores marcados por tintas esotéricas que adaptan diferentes animales y elementos dibujados sobre toda su piel. Gastan su concentración mística en activar tatuajes para ganar vuelo sutil, fuerza arrolladora o venenos letales a su favor. Cumplen un rol hiperversátil, brillando al cambiar de habilidades mágicas según el problema que enfrente el grupo de manera inmediata y sumamente efectiva.',
  'warrior-of-venom': 'Asesinos tóxicos que procesan en sus propias venas venenos letales capaces de derribar a colosos o multitudes. Utilizan su sangre contaminada para manchar sus armas, creando nubes ácidas y castigando a quienes osan herirlos directamente. Operan como atacantes de daño gradual letal, brillando al ignorar por completo las resistencias tóxicas y purificando cualquier veneno dañino en su organismo rápidamente.',
  'conquista': 'Cruzados de mano de hierro que siembran el pavor para paralizar y dominar a sus enemigos antes de golpearlos. Gastan sus conjuros y divinidad para aterrorizar multitudes y dañar pasivamente a cualquiera que quede atrapado en el horror total. Actúan como controladores de primera línea implacables, brillando al asegurar golpes vitales y devolver todo el daño psíquico a quien los ataque de forma fútil.',
  'redencion': 'Emisarios de la paz extrema que prefieren desviar los ataques y absorber dolor para evitar baños de sangre innecesarios. Utilizan su magia para convencer con el verbo, castigando con daño masivo a quienes lastiman a los inocentes frente a sus ojos. Cumplen el rol de defensores altruistas, brillando al proteger a todo el grupo curándose pasivamente en batalla, usando la violencia solo como el último recurso.',
  'corona': 'Defensores inquebrantables de los ideales soberanos que mantienen su formación sin importar el sacrificio personal. Gastan su poder divino para evitar que los monstruos huyan, atrayendo todo el peligro físico hacia su propia y blindada posición. Operan como tanques de zona y sanadores grupales tácticos, brillando al absorber golpes por otros e impedir mágicamente que sus aliados queden paralizados y expuestos al caos.',
  'genios-nobles': 'Guerreros elementales libres de pesadas armaduras que imbuyen cada uno de sus movimientos con magia genio majestuosa. Utilizan su destreza en esquiva para desatar tormentas, rocas, llamas o hielo puro sobre los enemigos con cada golpe fulminante de arma. Actúan como escaramuzadores resistentes veloces, brillando al compartir inmunidades en auras inmensas y repeler agresores con el poder desatado del viento furioso.',
  'vigilantes': 'Centinelas interplanares que protegen la realidad de horrores primigenios y demonios que se filtran por la oscuridad. Gastan su canalización para empujar criaturas lejanas, proteger mentes y mejorar la capacidad de alerta de toda la expedición aliada. Cumplen el rol de guardianes preventivos tácticos, brillando al liderar combates con tiradas rápidas de iniciativa y asegurar los bloqueos a portales interdimensionales oscuros.',
  'rompejuramentos-dmg': 'Renegados siniestros que emplean poderes necróticos formidables para someter a muertos y demonios bajo su oscuro mando. Utilizan magia pervertida para aterrorizar grupos completos, absorbiendo su energía, aumentando la fuerza de los suyos y su ira pasiva. Operan como líderes ofensivos aterradores, brillando al controlar hordas oscuras y rechazar fácilmente ataques físicos que desgarrarían a paladines normales puros.',
  'devocion': 'Paladines clásicos guiados por el honor, la justicia y la luz sagrada para expulsar la oscuridad del mundo. Gastan usos de su Canalizar Divinidad para convertir su arma en un faro de energía pura y ahuyentar a los seres corrompidos. Actúan como defensores implacables, brillando en las batallas contra muertos vivientes y demonios, donde su luz protege al grupo entero.',
  'gloria': 'Campeones egocéntricos y heroicos que buscan dejar su huella en la historia a través de proezas inigualables. Consumen poder divino para inspirar a sus aliados con velocidad sobrenatural y curación inmediata tras un ataque letal. Operan como vanguardia ágil, brillando en situaciones de asedio donde su fuerza física abrumadora y aura inspiradora los vuelven imparables.',
  'antiguos': 'Defensores de la luz natural y protectores de todo lo hermoso en el mundo. Utilizan magia druídica y juramentos divinos para atrapar enemigos con raíces y otorgar resistencia mágica a todo su escuadrón. Cumplen el rol de tanques antimagia absolutos, brillando al anular el daño letal de los hechiceros y proteger a las bestias salvajes y aliados con su escudo silvano.',
  'venganza': 'Paladines despiadados que juran dar caza a los peores villanos, sin importar las consecuencias personales. Gastan su poder divino para paralizar de miedo o perseguir a su presa elegida de forma incesante. Operan como asesinos con armadura pesada, brillando al aislar al enemigo más fuerte del campo y aniquilarlo sin darle tregua con daño concentrado ineludible.',
  'cadena': 'Brujos que forjan vínculos con seres extraplanares para obtener los familiares más letales y astutos de la realidad. Gastan magia táctica de apoyo, asumiendo un papel de espionaje perfecto. Brillan en la exploración y emboscada, ya que sus familiares invisibles atacan o envenenan mientras ellos se mantienen a una distancia segura para dictar el ritmo de la batalla mística.',
  'infernal': 'Pactantes de los archidiablos que consumen fuego y muerte para sobrevivir. Gastan su magia para invocar muros de llamas, bolas de fuego y curarse al eliminar enemigos, asumiendo el rol de daño expansivo brutal. Brillan al enfrentarse a hordas enteras, donde cada muerte los hace más resistentes, destacando por enviar almas débiles a través del infierno oscuro temporalmente.',
  'archihada': 'Siervos de los señores feéricos que entrelazan ilusiones, miedo y teleportación rápida en su magia caprichosa. Utilizan trucos sutiles para desaparecer frente a los atacantes, encantar multitudes enteras y eludir los golpes fatales. Operan como controladores engañosos, brillando al manipular el terreno social y desorientar formaciones militares sin recibir ni un solo arañazo.',
  'celestial': 'Brujos elegidos por entidades divinas para purgar con fuego sagrado y sanar con luz resplandeciente pura. Gastan energía mística para mantener a sus aliados con vida a distancia, asumiendo el rol inesperado de sanadores arcanos híbridos. Brillan en campañas contra la oscuridad extrema, donde su capacidad de sanar sin lanzar conjuros y resucitar solos los vuelve invaluables.',
  'primigenio': 'Sectarios de los grandes antiguos que infectan las mentes de sus enemigos con secretos cósmicos perturbadores. Gastan su poder mental para crear escudos psíquicos impenetrables y convertir a sus agresores en meras marionetas dóciles. Cumplen el rol de saboteadores mentales, brillando al confundir a la mayor amenaza física y leer mentes desde el anonimato oscuro perfecto.',
  'draconico': 'Hechiceros cuyo linaje escamoso les otorga la durabilidad, el terror y los alientos elementales de los dragones antiguos. Gastan Puntos de Hechicería para resistir el daño afín a su ancestro y volar libremente, asumiendo el rol de artillería duradera pura. Brillan al combinar magia destructiva inmensa con una resistencia física inusual para los lanzadores de hechizos puros.',
  'salvaje': 'Manipuladores del caos mágico que aceptan la impredecibilidad de sus poderes explosivos por el bien de la potencia extrema. Utilizan la marea del azar para manipular dados, asumiendo un papel de atacante arriesgado. Brillan al desatar efectos salvajes que curan, dañan o teletransportan de manera incontrolable, volviendo cada batalla una ruleta rusa letal y espectacular.',
};
